def comps_of(g):
    H,W=len(g),len(g[0]); seen=[[0]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=1; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==g[r][c] and not seen[x][y]:
                            seen[x][y]=1; st.append((x,y))
                res.append((cells,g[r][c]))
    return res

